INSERT INTO "traducao" ("id", "idioma", "hash_origem", "texto") VALUES
  (gen_random_uuid()::text, 'en', '2509865c9e894040', 'The documentation'),
  (gen_random_uuid()::text, 'en', '47416ae83c1518da', 'Click Documentation, in the top bar, to see how the tool was designed and built.'),
  (gen_random_uuid()::text, 'en', '814cee2bc52e0b0e', 'All about the tool'),
  (gen_random_uuid()::text, 'en', 'c5de0c6ddb5d6d60', 'Requirements, users, modeling, architecture, tests and specification, with the diagrams. The documentation is public, like the code.'),
  (gen_random_uuid()::text, 'en', '74e7f152803c2a70', 'How the tool was designed and built: requirements, users, modeling, architecture, tests and specification. It is public, like the code.'),
  (gen_random_uuid()::text, 'en', '2dc7b6ba77c8b451', 'Sections and documents'),
  (gen_random_uuid()::text, 'en', 'b606c308c43274ca', 'The tabs at the top separate the sections, and the documents are below them. A long document opens with the list of its parts, each on its own page, and at the end of each part you can go to the previous or the next one.'),
  (gen_random_uuid()::text, 'en', '4b3bea1f23c9e917', 'Diagrams'),
  (gen_random_uuid()::text, 'en', 'afb6fc1bb9573e17', 'Click a diagram to enlarge it to full screen, with zoom. The diagrams are in English in every language.'),
  (gen_random_uuid()::text, 'en', '88ef5514b955295c', 'The card next to each document says what it is, what it is for and who should read it. From there you can download the spreadsheets and open the file on GitHub.'),
  (gen_random_uuid()::text, 'en', 'c127b0481b4244db', 'The original is in Portuguese, with an English translation. In the other languages, the documentation appears in English. To translate it, fork the repository on GitHub and open a pull request.'),
  (gen_random_uuid()::text, 'es', '2509865c9e894040', 'La documentación'),
  (gen_random_uuid()::text, 'es', '47416ae83c1518da', 'Haga clic en Documentación, en la barra superior, para ver cómo se diseñó y construyó la herramienta.'),
  (gen_random_uuid()::text, 'es', '814cee2bc52e0b0e', 'Todo sobre la herramienta'),
  (gen_random_uuid()::text, 'es', 'c5de0c6ddb5d6d60', 'Requisitos, usuarios, modelado, arquitectura, pruebas y especificación, con los diagramas. La documentación es pública, como el código.'),
  (gen_random_uuid()::text, 'es', '74e7f152803c2a70', 'Cómo se diseñó y construyó la herramienta: requisitos, usuarios, modelado, arquitectura, pruebas y especificación. Es pública, como el código.'),
  (gen_random_uuid()::text, 'es', '2dc7b6ba77c8b451', 'Secciones y documentos'),
  (gen_random_uuid()::text, 'es', 'b606c308c43274ca', 'Las pestañas de arriba separan las secciones, y debajo de ellas están los documentos. Un documento largo se abre con la lista de sus partes, cada una en su propia página, y al final de cada parte puede pasar a la anterior o a la siguiente.'),
  (gen_random_uuid()::text, 'es', '4b3bea1f23c9e917', 'Diagramas'),
  (gen_random_uuid()::text, 'es', 'afb6fc1bb9573e17', 'Haga clic en un diagrama para ampliarlo a pantalla completa, con zoom. Los diagramas están en inglés en todos los idiomas.'),
  (gen_random_uuid()::text, 'es', '88ef5514b955295c', 'La ficha junto a cada documento indica qué es, para qué sirve y quién debe leerlo. Desde ahí puede descargar las hojas de cálculo y abrir el archivo en GitHub.'),
  (gen_random_uuid()::text, 'es', 'c127b0481b4244db', 'El original está en portugués, con traducción al inglés. En los demás idiomas, la documentación aparece en inglés. Para traducirla, haga un fork en GitHub y abra un pull request.'),
  (gen_random_uuid()::text, 'de', '2509865c9e894040', 'Die Dokumentation'),
  (gen_random_uuid()::text, 'de', '47416ae83c1518da', 'Klicken Sie oben in der Leiste auf Dokumentation, um zu sehen, wie das Tool entworfen und gebaut wurde.'),
  (gen_random_uuid()::text, 'de', '814cee2bc52e0b0e', 'Alles über das Tool'),
  (gen_random_uuid()::text, 'de', 'c5de0c6ddb5d6d60', 'Anforderungen, Nutzende, Modellierung, Architektur, Tests und Spezifikation, mit den Diagrammen. Die Dokumentation ist öffentlich, wie der Code.'),
  (gen_random_uuid()::text, 'de', '74e7f152803c2a70', 'Wie das Tool entworfen und gebaut wurde: Anforderungen, Nutzende, Modellierung, Architektur, Tests und Spezifikation. Sie ist öffentlich, wie der Code.'),
  (gen_random_uuid()::text, 'de', '2dc7b6ba77c8b451', 'Bereiche und Dokumente'),
  (gen_random_uuid()::text, 'de', 'b606c308c43274ca', 'Die Reiter oben trennen die Bereiche, darunter stehen die Dokumente. Ein langes Dokument öffnet mit der Liste seiner Teile, jeder auf einer eigenen Seite, und am Ende jedes Teils geht es zum vorherigen oder nächsten.'),
  (gen_random_uuid()::text, 'de', '4b3bea1f23c9e917', 'Diagramme'),
  (gen_random_uuid()::text, 'de', 'afb6fc1bb9573e17', 'Klicken Sie auf ein Diagramm, um es im Vollbild mit Zoom zu vergrößern. Die Diagramme sind in allen Sprachen auf Englisch.'),
  (gen_random_uuid()::text, 'de', '88ef5514b955295c', 'Die Karte neben jedem Dokument sagt, was es ist, wozu es dient und wer es lesen sollte. Dort laden Sie die Tabellen herunter und öffnen die Datei auf GitHub.'),
  (gen_random_uuid()::text, 'de', 'c127b0481b4244db', 'Das Original ist auf Portugiesisch, mit einer englischen Übersetzung. In den anderen Sprachen erscheint die Dokumentation auf Englisch. Um sie zu übersetzen, erstellen Sie einen Fork auf GitHub und öffnen Sie einen Pull Request.'),
  (gen_random_uuid()::text, 'fr', '2509865c9e894040', 'La documentation'),
  (gen_random_uuid()::text, 'fr', '47416ae83c1518da', 'Cliquez sur Documentation, dans la barre du haut, pour voir comment l’outil a été conçu et construit.'),
  (gen_random_uuid()::text, 'fr', '814cee2bc52e0b0e', 'Tout sur l’outil'),
  (gen_random_uuid()::text, 'fr', 'c5de0c6ddb5d6d60', 'Exigences, utilisateurs, modélisation, architecture, tests et spécification, avec les diagrammes. La documentation est publique, comme le code.'),
  (gen_random_uuid()::text, 'fr', '74e7f152803c2a70', 'Comment l’outil a été conçu et construit : exigences, utilisateurs, modélisation, architecture, tests et spécification. Elle est publique, comme le code.'),
  (gen_random_uuid()::text, 'fr', '2dc7b6ba77c8b451', 'Sections et documents'),
  (gen_random_uuid()::text, 'fr', 'b606c308c43274ca', 'Les onglets en haut séparent les sections, et les documents se trouvent en dessous. Un document long s’ouvre sur la liste de ses parties, chacune sur sa propre page, et à la fin de chaque partie vous passez à la précédente ou à la suivante.'),
  (gen_random_uuid()::text, 'fr', '4b3bea1f23c9e917', 'Diagrammes'),
  (gen_random_uuid()::text, 'fr', 'afb6fc1bb9573e17', 'Cliquez sur un diagramme pour l’agrandir en plein écran, avec zoom. Les diagrammes sont en anglais dans toutes les langues.'),
  (gen_random_uuid()::text, 'fr', '88ef5514b955295c', 'La fiche à côté de chaque document indique ce qu’il est, à quoi il sert et qui doit le lire. De là, vous téléchargez les tableurs et ouvrez le fichier sur GitHub.'),
  (gen_random_uuid()::text, 'fr', 'c127b0481b4244db', 'L’original est en portugais, avec une traduction anglaise. Dans les autres langues, la documentation s’affiche en anglais. Pour la traduire, faites un fork sur GitHub et ouvrez une pull request.'),
  (gen_random_uuid()::text, 'it', '2509865c9e894040', 'La documentazione'),
  (gen_random_uuid()::text, 'it', '47416ae83c1518da', 'Faccia clic su Documentazione, nella barra in alto, per vedere come è stato progettato e costruito lo strumento.'),
  (gen_random_uuid()::text, 'it', '814cee2bc52e0b0e', 'Tutto sullo strumento'),
  (gen_random_uuid()::text, 'it', 'c5de0c6ddb5d6d60', 'Requisiti, utenti, modellazione, architettura, test e specifica, con i diagrammi. La documentazione è pubblica, come il codice.'),
  (gen_random_uuid()::text, 'it', '74e7f152803c2a70', 'Come è stato progettato e costruito lo strumento: requisiti, utenti, modellazione, architettura, test e specifica. È pubblica, come il codice.'),
  (gen_random_uuid()::text, 'it', '2dc7b6ba77c8b451', 'Sezioni e documenti'),
  (gen_random_uuid()::text, 'it', 'b606c308c43274ca', 'Le schede in alto separano le sezioni, e sotto ci sono i documenti. Un documento lungo si apre con l’elenco delle sue parti, ognuna su una pagina propria, e alla fine di ogni parte si passa alla precedente o alla successiva.'),
  (gen_random_uuid()::text, 'it', '4b3bea1f23c9e917', 'Diagrammi'),
  (gen_random_uuid()::text, 'it', 'afb6fc1bb9573e17', 'Faccia clic su un diagramma per ingrandirlo a schermo intero, con lo zoom. I diagrammi sono in inglese in tutte le lingue.'),
  (gen_random_uuid()::text, 'it', '88ef5514b955295c', 'La scheda accanto a ogni documento dice che cos’è, a cosa serve e chi dovrebbe leggerlo. Da lì scarica i fogli di calcolo e apre il file su GitHub.'),
  (gen_random_uuid()::text, 'it', 'c127b0481b4244db', 'L’originale è in portoghese, con una traduzione inglese. Nelle altre lingue la documentazione appare in inglese. Per tradurla, faccia un fork su GitHub e apra una pull request.'),
  (gen_random_uuid()::text, 'nl', '2509865c9e894040', 'De documentatie'),
  (gen_random_uuid()::text, 'nl', '47416ae83c1518da', 'Klik op Documentatie, in de bovenste balk, om te zien hoe de tool is ontworpen en gebouwd.'),
  (gen_random_uuid()::text, 'nl', '814cee2bc52e0b0e', 'Alles over de tool'),
  (gen_random_uuid()::text, 'nl', 'c5de0c6ddb5d6d60', 'Eisen, gebruikers, modellering, architectuur, tests en specificatie, met de diagrammen. De documentatie is openbaar, net als de code.'),
  (gen_random_uuid()::text, 'nl', '74e7f152803c2a70', 'Hoe de tool is ontworpen en gebouwd: eisen, gebruikers, modellering, architectuur, tests en specificatie. Ze is openbaar, net als de code.'),
  (gen_random_uuid()::text, 'nl', '2dc7b6ba77c8b451', 'Secties en documenten'),
  (gen_random_uuid()::text, 'nl', 'b606c308c43274ca', 'De tabbladen bovenaan scheiden de secties, en daaronder staan de documenten. Een lang document opent met de lijst van zijn delen, elk op een eigen pagina, en aan het einde van elk deel gaat u naar het vorige of het volgende.'),
  (gen_random_uuid()::text, 'nl', '4b3bea1f23c9e917', 'Diagrammen'),
  (gen_random_uuid()::text, 'nl', 'afb6fc1bb9573e17', 'Klik op een diagram om het schermvullend te vergroten, met zoom. De diagrammen zijn in alle talen in het Engels.'),
  (gen_random_uuid()::text, 'nl', '88ef5514b955295c', 'De kaart naast elk document vertelt wat het is, waarvoor het dient en wie het zou moeten lezen. Daar downloadt u de spreadsheets en opent u het bestand op GitHub.'),
  (gen_random_uuid()::text, 'nl', 'c127b0481b4244db', 'Het origineel is in het Portugees, met een Engelse vertaling. In de andere talen verschijnt de documentatie in het Engels. Om haar te vertalen, maakt u een fork op GitHub en opent u een pull request.'),
  (gen_random_uuid()::text, 'da', '2509865c9e894040', 'Dokumentationen'),
  (gen_random_uuid()::text, 'da', '47416ae83c1518da', 'Klik på Dokumentation i den øverste bjælke for at se, hvordan værktøjet blev udtænkt og bygget.'),
  (gen_random_uuid()::text, 'da', '814cee2bc52e0b0e', 'Alt om værktøjet'),
  (gen_random_uuid()::text, 'da', 'c5de0c6ddb5d6d60', 'Krav, brugere, modellering, arkitektur, test og specifikation, med diagrammerne. Dokumentationen er offentlig, ligesom koden.'),
  (gen_random_uuid()::text, 'da', '74e7f152803c2a70', 'Hvordan værktøjet blev udtænkt og bygget: krav, brugere, modellering, arkitektur, test og specifikation. Den er offentlig, ligesom koden.'),
  (gen_random_uuid()::text, 'da', '2dc7b6ba77c8b451', 'Sektioner og dokumenter'),
  (gen_random_uuid()::text, 'da', 'b606c308c43274ca', 'Fanerne øverst adskiller sektionerne, og dokumenterne ligger under dem. Et langt dokument åbner med listen over dets dele, hver på sin egen side, og i slutningen af hver del går du til den forrige eller den næste.'),
  (gen_random_uuid()::text, 'da', '4b3bea1f23c9e917', 'Diagrammer'),
  (gen_random_uuid()::text, 'da', 'afb6fc1bb9573e17', 'Klik på et diagram for at forstørre det til fuld skærm, med zoom. Diagrammerne er på engelsk på alle sprog.'),
  (gen_random_uuid()::text, 'da', '88ef5514b955295c', 'Kortet ved siden af hvert dokument fortæller, hvad det er, hvad det bruges til, og hvem der bør læse det. Derfra downloader du regnearkene og åbner filen på GitHub.'),
  (gen_random_uuid()::text, 'da', 'c127b0481b4244db', 'Originalen er på portugisisk, med en engelsk oversættelse. På de andre sprog vises dokumentationen på engelsk. For at oversætte den skal du lave en fork på GitHub og åbne en pull request.'),
  (gen_random_uuid()::text, 'sv', '2509865c9e894040', 'Dokumentationen'),
  (gen_random_uuid()::text, 'sv', '47416ae83c1518da', 'Klicka på Dokumentation i den översta raden för att se hur verktyget utformades och byggdes.'),
  (gen_random_uuid()::text, 'sv', '814cee2bc52e0b0e', 'Allt om verktyget'),
  (gen_random_uuid()::text, 'sv', 'c5de0c6ddb5d6d60', 'Krav, användare, modellering, arkitektur, tester och specifikation, med diagrammen. Dokumentationen är offentlig, precis som koden.'),
  (gen_random_uuid()::text, 'sv', '74e7f152803c2a70', 'Hur verktyget utformades och byggdes: krav, användare, modellering, arkitektur, tester och specifikation. Den är offentlig, precis som koden.'),
  (gen_random_uuid()::text, 'sv', '2dc7b6ba77c8b451', 'Avsnitt och dokument'),
  (gen_random_uuid()::text, 'sv', 'b606c308c43274ca', 'Flikarna överst skiljer avsnitten åt, och dokumenten finns under dem. Ett långt dokument öppnas med listan över dess delar, var och en på en egen sida, och i slutet av varje del går du till den föregående eller nästa.'),
  (gen_random_uuid()::text, 'sv', '4b3bea1f23c9e917', 'Diagram'),
  (gen_random_uuid()::text, 'sv', 'afb6fc1bb9573e17', 'Klicka på ett diagram för att förstora det till helskärm, med zoom. Diagrammen är på engelska på alla språk.'),
  (gen_random_uuid()::text, 'sv', '88ef5514b955295c', 'Kortet bredvid varje dokument berättar vad det är, vad det är till för och vem som bör läsa det. Därifrån laddar du ner kalkylbladen och öppnar filen på GitHub.'),
  (gen_random_uuid()::text, 'sv', 'c127b0481b4244db', 'Originalet är på portugisiska, med en engelsk översättning. På de andra språken visas dokumentationen på engelska. För att översätta den, gör en fork på GitHub och öppna en pull request.'),
  (gen_random_uuid()::text, 'nb', '2509865c9e894040', 'Dokumentasjonen'),
  (gen_random_uuid()::text, 'nb', '47416ae83c1518da', 'Klikk på Dokumentasjon i den øverste linjen for å se hvordan verktøyet ble utformet og bygget.'),
  (gen_random_uuid()::text, 'nb', '814cee2bc52e0b0e', 'Alt om verktøyet'),
  (gen_random_uuid()::text, 'nb', 'c5de0c6ddb5d6d60', 'Krav, brukere, modellering, arkitektur, tester og spesifikasjon, med diagrammene. Dokumentasjonen er offentlig, som koden.'),
  (gen_random_uuid()::text, 'nb', '74e7f152803c2a70', 'Hvordan verktøyet ble utformet og bygget: krav, brukere, modellering, arkitektur, tester og spesifikasjon. Den er offentlig, som koden.'),
  (gen_random_uuid()::text, 'nb', '2dc7b6ba77c8b451', 'Seksjoner og dokumenter'),
  (gen_random_uuid()::text, 'nb', 'b606c308c43274ca', 'Fanene øverst skiller seksjonene, og dokumentene ligger under dem. Et langt dokument åpner med listen over delene, hver på sin egen side, og på slutten av hver del går du til forrige eller neste.'),
  (gen_random_uuid()::text, 'nb', '4b3bea1f23c9e917', 'Diagrammer'),
  (gen_random_uuid()::text, 'nb', 'afb6fc1bb9573e17', 'Klikk på et diagram for å forstørre det til fullskjerm, med zoom. Diagrammene er på engelsk på alle språk.'),
  (gen_random_uuid()::text, 'nb', '88ef5514b955295c', 'Kortet ved siden av hvert dokument forteller hva det er, hva det er til for og hvem som bør lese det. Derfra laster du ned regnearkene og åpner filen på GitHub.'),
  (gen_random_uuid()::text, 'nb', 'c127b0481b4244db', 'Originalen er på portugisisk, med en engelsk oversettelse. På de andre språkene vises dokumentasjonen på engelsk. For å oversette den, lag en fork på GitHub og åpne en pull request.'),
  (gen_random_uuid()::text, 'fi', '2509865c9e894040', 'Dokumentaatio'),
  (gen_random_uuid()::text, 'fi', '47416ae83c1518da', 'Napsauta yläpalkin Dokumentaatio-kohtaa nähdäksesi, miten työkalu suunniteltiin ja rakennettiin.'),
  (gen_random_uuid()::text, 'fi', '814cee2bc52e0b0e', 'Kaikki työkalusta'),
  (gen_random_uuid()::text, 'fi', 'c5de0c6ddb5d6d60', 'Vaatimukset, käyttäjät, mallinnus, arkkitehtuuri, testit ja määrittely kaavioineen. Dokumentaatio on julkinen, kuten koodikin.'),
  (gen_random_uuid()::text, 'fi', '74e7f152803c2a70', 'Miten työkalu suunniteltiin ja rakennettiin: vaatimukset, käyttäjät, mallinnus, arkkitehtuuri, testit ja määrittely. Se on julkinen, kuten koodikin.'),
  (gen_random_uuid()::text, 'fi', '2dc7b6ba77c8b451', 'Osiot ja asiakirjat'),
  (gen_random_uuid()::text, 'fi', 'b606c308c43274ca', 'Ylhäällä olevat välilehdet erottavat osiot, ja niiden alla ovat asiakirjat. Pitkä asiakirja avautuu osiensa luettelolla, jokainen osa omalla sivullaan, ja kunkin osan lopussa voit siirtyä edelliseen tai seuraavaan.'),
  (gen_random_uuid()::text, 'fi', '4b3bea1f23c9e917', 'Kaaviot'),
  (gen_random_uuid()::text, 'fi', 'afb6fc1bb9573e17', 'Napsauta kaaviota suurentaaksesi sen koko näytölle zoomin kanssa. Kaaviot ovat englanniksi kaikilla kielillä.'),
  (gen_random_uuid()::text, 'fi', '88ef5514b955295c', 'Kunkin asiakirjan vieressä oleva kortti kertoo, mikä se on, mihin se on tarkoitettu ja kenen kannattaa lukea se. Sieltä voit ladata laskentataulukot ja avata tiedoston GitHubissa.'),
  (gen_random_uuid()::text, 'fi', 'c127b0481b4244db', 'Alkuperäinen on portugaliksi, ja siitä on englanninkielinen käännös. Muilla kielillä dokumentaatio näkyy englanniksi. Jos haluat kääntää sen, tee fork GitHubissa ja avaa pull request.'),
  (gen_random_uuid()::text, 'et', '2509865c9e894040', 'Dokumentatsioon'),
  (gen_random_uuid()::text, 'et', '47416ae83c1518da', 'Klõpsake ülemisel ribal Dokumentatsioon, et näha, kuidas tööriist kavandati ja ehitati.'),
  (gen_random_uuid()::text, 'et', '814cee2bc52e0b0e', 'Kõik tööriistast'),
  (gen_random_uuid()::text, 'et', 'c5de0c6ddb5d6d60', 'Nõuded, kasutajad, modelleerimine, arhitektuur, testid ja spetsifikatsioon koos diagrammidega. Dokumentatsioon on avalik, nagu ka kood.'),
  (gen_random_uuid()::text, 'et', '74e7f152803c2a70', 'Kuidas tööriist kavandati ja ehitati: nõuded, kasutajad, modelleerimine, arhitektuur, testid ja spetsifikatsioon. See on avalik, nagu ka kood.'),
  (gen_random_uuid()::text, 'et', '2dc7b6ba77c8b451', 'Jaotised ja dokumendid'),
  (gen_random_uuid()::text, 'et', 'b606c308c43274ca', 'Ülal olevad sakid eraldavad jaotisi ja nende all on dokumendid. Pikk dokument avaneb osade loendiga, iga osa omal lehel, ning iga osa lõpus saate liikuda eelmisele või järgmisele.'),
  (gen_random_uuid()::text, 'et', '4b3bea1f23c9e917', 'Diagrammid'),
  (gen_random_uuid()::text, 'et', 'afb6fc1bb9573e17', 'Klõpsake diagrammil, et see suumiga täisekraanile suurendada. Diagrammid on kõigis keeltes inglise keeles.'),
  (gen_random_uuid()::text, 'et', '88ef5514b955295c', 'Iga dokumendi kõrval olev kaart ütleb, mis see on, milleks see on ja kes peaks seda lugema. Sealt saate alla laadida tabelid ja avada faili GitHubis.'),
  (gen_random_uuid()::text, 'et', 'c127b0481b4244db', 'Originaal on portugali keeles, ingliskeelse tõlkega. Teistes keeltes kuvatakse dokumentatsioon inglise keeles. Selle tõlkimiseks tehke GitHubis fork ja avage pull request.'),
  (gen_random_uuid()::text, 'pl', '2509865c9e894040', 'Dokumentacja'),
  (gen_random_uuid()::text, 'pl', '47416ae83c1518da', 'Kliknij Dokumentacja na górnym pasku, aby zobaczyć, jak narzędzie zostało zaprojektowane i zbudowane.'),
  (gen_random_uuid()::text, 'pl', '814cee2bc52e0b0e', 'Wszystko o narzędziu'),
  (gen_random_uuid()::text, 'pl', 'c5de0c6ddb5d6d60', 'Wymagania, użytkownicy, modelowanie, architektura, testy i specyfikacja, wraz z diagramami. Dokumentacja jest publiczna, tak jak kod.'),
  (gen_random_uuid()::text, 'pl', '74e7f152803c2a70', 'Jak narzędzie zostało zaprojektowane i zbudowane: wymagania, użytkownicy, modelowanie, architektura, testy i specyfikacja. Jest publiczna, tak jak kod.'),
  (gen_random_uuid()::text, 'pl', '2dc7b6ba77c8b451', 'Sekcje i dokumenty'),
  (gen_random_uuid()::text, 'pl', 'b606c308c43274ca', 'Karty u góry oddzielają sekcje, a pod nimi znajdują się dokumenty. Długi dokument otwiera się listą jego części, każda na osobnej stronie, a na końcu każdej części przechodzisz do poprzedniej lub następnej.'),
  (gen_random_uuid()::text, 'pl', '4b3bea1f23c9e917', 'Diagramy'),
  (gen_random_uuid()::text, 'pl', 'afb6fc1bb9573e17', 'Kliknij diagram, aby powiększyć go na pełny ekran, z powiększeniem. Diagramy są po angielsku we wszystkich językach.'),
  (gen_random_uuid()::text, 'pl', '88ef5514b955295c', 'Karta obok każdego dokumentu mówi, czym jest, do czego służy i kto powinien go przeczytać. Stamtąd pobierzesz arkusze kalkulacyjne i otworzysz plik na GitHubie.'),
  (gen_random_uuid()::text, 'pl', 'c127b0481b4244db', 'Oryginał jest po portugalsku, z tłumaczeniem na angielski. W pozostałych językach dokumentacja wyświetla się po angielsku. Aby ją przetłumaczyć, zrób fork na GitHubie i otwórz pull request.'),
  (gen_random_uuid()::text, 'cs', '2509865c9e894040', 'Dokumentace'),
