  (gen_random_uuid()::text, 'cs', 'c127b0481b4244db', 'Originál je v portugalštině, s anglickým překladem. V ostatních jazycích se dokumentace zobrazuje anglicky. Chcete-li ji přeložit, vytvořte fork na GitHubu a otevřete pull request.'),
  (gen_random_uuid()::text, 'sk', '2509865c9e894040', 'Dokumentácia'),
