  (gen_random_uuid()::text, 'sk', '74e7f152803c2a70', 'Ako bol nástroj navrhnutý a vytvorený: požiadavky, používatelia, modelovanie, architektúra, testy a špecifikácia. Je verejná, rovnako ako kód.'),
