  (gen_random_uuid()::text, 'hu', 'c5de0c6ddb5d6d60', 'Követelmények, felhasználók, modellezés, architektúra, tesztek és specifikáció, diagramokkal. A dokumentáció nyilvános, akárcsak a kód.'),
  (gen_random_uuid()::text, 'hu', '74e7f152803c2a70', 'Hogyan tervezték és készítették az eszközt: követelmények, felhasználók, modellezés, architektúra, tesztek és specifikáció. Nyilvános, akárcsak a kód.'),
  (gen_random_uuid()::text, 'hu', '2dc7b6ba77c8b451', 'Szakaszok és dokumentumok'),
